'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nav=[['inicio','home','Inicio'],['despensa','box','Despensa'],['recetas','pot','Qué cocino'],['compra','bag','Compra'],['hogar','people','Hogar']];
const state={page:'inicio',location:'Todas',search:'',recipeTab:'ready',servings:2,allergies:['Gluten'],shop:[],members:['Clara','Dani']};
let lots=[{id:1,name:'Tomates',qty:500,unit:'g',place:'Nevera',date:'2026-10-10',type:'Caducidad',icon:'🍅'},{id:2,name:'Espinacas',qty:200,unit:'g',place:'Nevera',date:'2026-10-09',type:'Caducidad',icon:'🥬'},{id:3,name:'Tomates',qty:300,unit:'g',place:'Nevera',date:'2026-10-13',type:'Caducidad',icon:'🍅'},{id:4,name:'Arroz',qty:800,unit:'g',place:'Despensa',date:'',type:'',icon:'🍚'},{id:5,name:'Aceite de oliva',qty:250,unit:'ml',place:'Despensa',date:'',type:'',icon:'🫒'},{id:6,name:'Sal',qty:200,unit:'g',place:'Despensa',date:'',type:'',icon:'🧂'},{id:7,name:'Yogur',qty:2,unit:'ud',place:'Nevera',date:'2026-10-08',type:'Caducidad',icon:'🥛'},{id:8,name:'Huevos',qty:4,unit:'ud',place:'Nevera',date:'2026-10-07',type:'Caducidad',icon:'🥚'},{id:9,name:'Avena',qty:300,unit:'g',place:'Despensa',date:'2026-10-05',type:'Consumo preferente',icon:'🌾'},{id:10,name:'Guisantes',qty:400,unit:'g',place:'Congelador',date:'2026-12-10',type:'Consumo preferente',icon:'🫛'}];
const recipes=[{id:'arroz',name:'Arroz con tomate y espinacas',time:25,icon:'🍲',allergens:[],complete:true,vegetarian:true,ingredients:[['Arroz',160,'g'],['Tomates',300,'g'],['Espinacas',100,'g'],['Aceite de oliva',20,'ml'],['Sal',2,'g']],steps:['Lava los tomates y las espinacas. Corta los tomates en dados.','Cuece el arroz con agua siguiendo las indicaciones del envase.','Calienta el aceite, cocina el tomate y añade las espinacas.','Mezcla con el arroz y ajusta la sal. Revisa las cantidades antes de confirmar.']},{id:'garbanzos',name:'Garbanzos con tomate',time:20,icon:'🥣',allergens:[],complete:true,vegetarian:true,ingredients:[['Garbanzos cocidos',400,'g'],['Tomates',250,'g'],['Aceite de oliva',20,'ml'],['Sal',2,'g']],steps:['Escurre los garbanzos y lava los tomates.','Cocina el tomate con el aceite.','Añade los garbanzos y calienta. Ajusta la sal.']},{id:'tortilla',name:'Tortilla de espinacas',time:15,icon:'🍳',allergens:['Huevo'],complete:true,vegetarian:true,ingredients:[['Huevos',4,'ud'],['Espinacas',150,'g'],['Aceite de oliva',20,'ml'],['Sal',2,'g']],steps:['Lava y cocina las espinacas.','Bate los huevos, incorpora las espinacas y cocina la tortilla.']},{id:'pasta',name:'Pasta con tomate',time:20,icon:'🍝',allergens:['Gluten'],complete:true,vegetarian:true,ingredients:[],steps:[]},{id:'sopa',name:'Sopa de verduras',time:20,icon:'🥣',allergens:[],complete:false,vegetarian:true,ingredients:[],steps:[]}];
const usable=l=>!l.date||l.date>='2026-10-09';
const available=(name,unit)=>lots.filter(l=>l.name===name&&l.unit===unit&&usable(l)).reduce((sum,l)=>sum+l.qty,0);
const scaled=r=>r.ingredients.map(([name,qty,unit])=>({name,qty:qty*state.servings/2,unit}));
const missing=r=>scaled(r).map(i=>({...i,qty:Math.max(0,i.qty-available(i.name,i.unit))})).filter(i=>i.qty>0);
const allowed=r=>r.complete&&!r.allergens.some(a=>state.allergies.includes(a));
const plate=`<svg viewBox="0 0 300 300" aria-hidden="true"><ellipse cx="154" cy="260" rx="108" ry="16" fill="#c5d3b6"/><circle cx="150" cy="145" r="118" fill="#faf9f1"/><circle cx="150" cy="145" r="96" fill="none" stroke="#e4e8da" stroke-width="3"/><circle cx="150" cy="145" r="83" fill="#f5e6bd"/><g fill="#deaf61"><ellipse cx="109" cy="102" rx="4" ry="8" transform="rotate(40 109 102)"/><ellipse cx="167" cy="86" rx="4" ry="8"/><ellipse cx="133" cy="171" rx="4" ry="8" transform="rotate(60 133 171)"/><ellipse cx="196" cy="145" rx="4" ry="8"/><ellipse cx="112" cy="205" rx="4" ry="8"/><ellipse cx="187" cy="196" rx="4" ry="8"/></g><g fill="#e48365" stroke="#b95e46" stroke-width="1.5"><path d="m85 130 27-14 12 28-29 12Z"/><path d="m163 107 28-4 6 24-29 8Z"/><path d="m149 180 27-10 12 30-28 11Z"/><path d="m96 179 25-12 9 20-21 13Z"/></g><g fill="#557c44"><ellipse cx="135" cy="92" rx="13" ry="26" transform="rotate(-35 135 92)"/><ellipse cx="188" cy="161" rx="14" ry="27" transform="rotate(35 188 161)"/><ellipse cx="123" cy="145" rx="12" ry="23" transform="rotate(55 123 145)"/><ellipse cx="144" cy="210" rx="12" ry="21" transform="rotate(80 144 210)"/></g><g stroke="#8ca173" stroke-width="1.4"><path d="m122 73 26 37m55 29-30 44m-66-49 33 24m-12 50 34 6"/></g><g fill="#709c53"><ellipse cx="262" cy="75" rx="13" ry="27" transform="rotate(45 262 75)"/><ellipse cx="238" cy="51" rx="11" ry="23" transform="rotate(-20 238 51)"/></g><path d="m257 62-24 42" stroke="#628248" stroke-width="2"/></svg>`;
const intro=(label,title,copy)=>`<div class="eyebrow">${label}</div><h1>${title}</h1><p class="intro">${copy}</p>`;
const row=l=>{let label=!l.date?'Fecha desconocida':l.date==='2026-10-09'?'Hoy':l.date==='2026-10-10'?'Mañana':l.date.split('-').reverse().slice(0,2).join('/');if(l.date&&l.date<'2026-10-09') label=l.type==='Caducidad'?'Caducado':'Preferente superado';return `<div class="food-row"><span class="food-icon" aria-hidden="true">${l.icon}</span><div class="food-main"><strong>${esc(l.name)}</strong><small>${l.qty} ${esc(l.unit)} · ${esc(l.place)}${l.date?' · '+l.type:''}</small></div><span class="date-label ${l.date&&l.date<'2026-10-09'&&l.type==='Caducidad'?'red':l.date&&l.date<='2026-10-11'?'warning':''}">${label}</span>${state.page==='despensa'?`<button class="text-link" data-action="out" data-id="${l.id}" aria-label="Registrar salida de ${esc(l.name)}, lote ${l.id}">Salida</button>`:''}</div>`};
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),4500);}
function open(html){$('dialog-content').innerHTML=html;$('dialog').showModal();}
$('close-dialog').onclick=()=>$('dialog').close();
function home(){const expired=lots.filter(l=>l.date&&l.date<'2026-10-09'&&l.type==='Caducidad');const soon=lots.filter(l=>l.date&&l.date>='2026-10-09'&&l.date<='2026-10-11');return intro('COCINA A TIEMPO','Lo bueno está en tu despensa.','Aprovecha lo que tienes y elige qué cocinar hoy.')+`<article class="hero"><div class="hero-copy"><span class="eyebrow">PARA COCINAR HOY</span><h2>Arroz con tomate<br>y espinacas</h2><p>Una idea para aprovechar las espinacas de hoy y los tomates de mañana.</p><div class="meta"><span class="pill">25 min</span><span class="pill">${state.servings} raciones</span><span class="pill">Vegetariana</span></div><button class="button coral" data-action="recipe" data-id="arroz">Ver receta <span aria-hidden="true">→</span></button></div><div class="hero-art">${plate}<span class="art-label">CON LO QUE YA TIENES</span></div></article><div class="grid-two"><section class="panel"><div class="heading-row"><h2>Primero, estos alimentos</h2><a class="text-link" href="#despensa">Ver despensa</a></div><p class="hint">Hoy y los próximos 2 días.</p>${soon.length?soon.map(row).join(''):'<p>Sin alimentos próximos a su fecha.</p>'}</section><section><div class="notice"><strong>${expired.length} lotes con caducidad superada</strong>No se incluyen en las sugerencias. Revisa el descarte.<br><a class="text-link" href="#despensa">Revisar lotes →</a></div><div class="panel"><h3>Una despensa a tu ritmo</h3><p class="hint">No hace falta registrar toda la compra para empezar. Añade lo que quieras aprovechar.</p><button class="button secondary" data-action="add">+ Añadir alimento</button></div></section></div>`;}
function pantry(){const filtered=lots.filter(l=>(state.location==='Todas'||l.place===state.location)&&l.name.toLocaleLowerCase('es').includes(state.search.toLocaleLowerCase('es')));return intro('TUS ALIMENTOS','Despensa','Cada compra conserva su lote y su fecha.')+`<div class="heading-row"><span class="hint">${lots.length} lotes ficticios</span><button class="button coral" data-action="add">+ Añadir alimento</button></div><div class="toolbar"><input id="search" type="search" aria-label="Buscar alimento" placeholder="Buscar en la despensa" value="${esc(state.search)}"><select id="place-filter" aria-label="Filtrar por ubicación">${['Todas','Nevera','Congelador','Despensa'].map(x=>`<option ${x===state.location?'selected':''}>${x}</option>`).join('')}</select></div><div class="notice prefer"><strong>Caducidad y consumo preferente son distintos</strong>Los lotes con fecha superada permanecen visibles. El consumo preferente requiere revisar su estado; no se considera disponible automáticamente.</div><section class="panel">${filtered.length?filtered.map(row).join(''):'<p class="empty">No hay alimentos en esta vista.</p>'}</section>`;}
function recipeCard(r){const m=missing(r);return `<article class="recipe-card"><div class="recipe-art" aria-hidden="true">${r.icon}</div><div class="recipe-copy"><div class="eyebrow">${r.time} MIN · ${state.servings} RACIONES</div><h3>${r.name}</h3><p>${m.length?'Falta: '+m.map(i=>`${i.qty} ${i.unit} de ${i.name.toLowerCase()}`).join(', ')+'.':'Tienes los ingredientes en cantidades suficientes.'}</p><button class="button secondary" data-action="recipe" data-id="${r.id}">Ver receta →</button></div></article>`;}
function cooking(){const list=recipes.filter(allowed).filter(r=>state.recipeTab==='ready'?missing(r).length===0:missing(r).length>0);return intro('IDEAS PARA HOY','Qué cocino','Recetas que aprovechan los alimentos utilizables de tu hogar.')+`<div class="toolbar"><select id="time-filter" aria-label="Tiempo disponible"><option value="60">Hasta 60 minutos</option><option value="20">Hasta 20 minutos</option></select><label class="checkbox-line"><input id="vegetarian" type="checkbox"> Solo vegetarianas</label></div><p class="hint">Exclusión ficticia del hogar: ${state.allergies.join(', ')||'ninguna'}. Información incompleta de alérgenos: receta excluida. Comprueba siempre etiquetas y contaminación cruzada.</p><div class="chips"><button class="chip ${state.recipeTab==='ready'?'active':''}" data-action="recipe-tab" data-id="ready">Puedes cocinar</button><button class="chip ${state.recipeTab==='buy'?'active':''}" data-action="recipe-tab" data-id="buy">Necesitas comprar</button></div><div class="cards" id="recipe-cards">${list.length?list.map(recipeCard).join(''):'<p class="empty">No hay propuestas con estos filtros.</p>'}</div>`;}
function shopping(){return intro('PARA LA PRÓXIMA COMPRA','Compra','Marca lo comprado y revísalo antes de incorporarlo a la despensa.')+`<section class="panel"><div class="heading-row"><h2>Lista del hogar</h2><button class="button secondary small" data-action="shop-add">+ Añadir</button></div>${state.shop.length?state.shop.map((i,n)=>`<div class="shop-row ${i.bought?'bought':''}"><input type="checkbox" aria-label="Marcar ${esc(i.name)} como comprado" data-shop="${n}" ${i.bought?'checked':''}><div class="food-main"><strong>${esc(i.name)}</strong><small>${i.qty} ${esc(i.unit)}${i.bought?' · Pendiente de incorporar':''}</small></div>${i.bought?`<button class="text-link" data-action="incorporate" data-id="${n}">Incorporar</button>`:''}<button class="icon-button" data-action="shop-remove" data-id="${n}" aria-label="Quitar ${esc(i.name)}">×</button></div>`).join(''):'<div class="empty"><div style="font-size:36px" aria-hidden="true">🧺</div><h3>La lista está vacía</h3><p>Añade un producto o los ingredientes que faltan en una receta.</p><a class="button secondary" href="#recetas">Explorar recetas</a></div>'}</section><p class="hint">Marcar como comprado no cambia las existencias. La incorporación crea un nuevo lote ficticio tras revisarlo.</p>`;}
function household(){return intro('HOGAR DEL OLIVO','A vuestra manera','Miembros, raciones y preferencias de este hogar ficticio.')+`<div class="grid-two"><section class="panel"><div class="heading-row"><h2>Miembros</h2><button class="text-link" data-action="invite">Invitar</button></div>${state.members.map((m,i)=>`<div class="member"><span class="avatar">${m[0]}</span><div><strong>${m} · ficticio</strong><div class="hint">${i?'Miembro':'Administradora'}</div></div>${i?`<button class="text-link" data-action="remove-member">Retirar</button>`:''}</div>`).join('')}<p class="hint">Las invitaciones y retiradas de esta maqueta son simuladas.</p></section><section class="panel"><h2>Para cocinar</h2><label class="settings-row">Raciones habituales<input id="servings" type="number" min="1" max="8" value="${state.servings}"></label><div class="settings-row"><span>Aviso de proximidad</span><strong>2 días</strong></div><div class="settings-row"><span>Zona horaria</span><strong>Madrid</strong></div></section></div><section class="panel"><h2>Alergias ficticias del hogar</h2><p class="hint">Solo perfiles de demostración. No introduzcas información sanitaria real. Las exclusiones se aplican a todas las sugerencias.</p><div class="chips">${['Gluten','Huevo','Leche','Frutos de cáscara'].map(a=>`<button class="chip ${state.allergies.includes(a)?'active':''}" aria-pressed="${state.allergies.includes(a)}" data-action="allergy" data-id="${a}">${a}</button>`).join('')}</div><p class="hint">Comprueba etiquetas y posible contaminación cruzada. El catálogo ilustrativo no acredita seguridad alimentaria.</p><button class="text-link" data-action="privacy">Privacidad: qué falta antes de usar datos reales →</button></section><section class="panel"><h3>Voz pendiente de comprobar</h3><p class="hint">El último intento terminó con error de red. Esta maqueta utiliza siempre el formulario. No activa el micrófono.</p><a class="text-link" href="index.html">Volver a la prueba de dictado →</a></section>`;}
function render(){const title=nav.find(n=>n[0]===state.page)?.[2]||'Inicio';document.title=title+' · Cocina a Tiempo';for(const id of ['desktop-nav','mobile-nav'])$(id).innerHTML=nav.map(([key,icon,label])=>`<a href="#${key}" ${key===state.page?'aria-current="page"':''}><svg aria-hidden="true"><use href="#i-${icon}"/></svg>${label}</a>`).join('');$('content').innerHTML=({inicio:home,despensa:pantry,recetas:cooking,compra:shopping,hogar:household}[state.page]||home)();bindFilters();}
function route(){state.page=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'inicio';render();window.scrollTo(0,0);$('content').focus({preventScroll:true});}
window.addEventListener('hashchange',route);
function bindFilters(){if($('search'))$('search').oninput=e=>{state.search=e.target.value;const pos=e.target.selectionStart;render();$('search').focus();$('search').setSelectionRange(pos,pos);};if($('place-filter'))$('place-filter').onchange=e=>{state.location=e.target.value;render();};if($('servings'))$('servings').onchange=e=>{const v=Number(e.target.value);if(Number.isInteger(v)&&v>=1&&v<=8){state.servings=v;toast('Raciones ficticias actualizadas.');}else e.target.value=state.servings;};for(const id of ['time-filter','vegetarian'])if($(id))$(id).onchange=()=>{const list=recipes.filter(allowed).filter(r=>r.time<=Number($('time-filter').value)&&(!$('vegetarian').checked||r.vegetarian)).filter(r=>state.recipeTab==='ready'?missing(r).length===0:missing(r).length>0);$('recipe-cards').innerHTML=list.length?list.map(recipeCard).join(''):'<p class="empty">No hay propuestas con estos filtros.</p>';};}
function recipe(id){const r=recipes.find(r=>r.id===id);if(!allowed(r)){toast('La receta está excluida por las alergias ficticias del hogar.');return;}const m=missing(r);open(`<h2>${r.name}</h2><div class="meta"><span class="pill">${r.time} min</span><span class="pill">${state.servings} raciones</span></div><label>Raciones de esta demostración<select id="recipe-servings">${[1,2,3,4,5,6,7,8].map(n=>`<option ${n===state.servings?'selected':''}>${n}</option>`).join('')}</select></label><ul class="review-list">${scaled(r).map(i=>`<li><span>${i.name}</span><span>${i.qty} ${i.unit}${available(i.name,i.unit)<i.qty?' · falta cantidad':''}</span></li>`).join('')}</ul><h3>Preparación</h3><ol>${r.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="hint">Receta ilustrativa. Verifica etiquetas y contaminación cruzada. Los lotes caducados y de consumo preferente superado se excluyen.</p><div class="dialog-actions"><button class="button coral" data-action="${m.length?'missing':'cook-review'}" data-id="${r.id}">${m.length?'Añadir lo que falta a Compra':'Revisar antes de cocinar'}</button></div>`);$('recipe-servings').onchange=e=>{state.servings=Number(e.target.value);$('dialog').close();recipe(id);};}
function cookReview(id){const r=recipes.find(r=>r.id===id);if(missing(r).length){toast('Las cantidades han cambiado. Revisa la receta.');return;}const deductions=[];for(const i of scaled(r)){let pending=i.qty;for(const l of lots.filter(l=>l.name===i.name&&l.unit===i.unit&&usable(l)).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'))){const used=Math.min(pending,l.qty);if(used)deductions.push({id:l.id,name:l.name,qty:used,unit:l.unit,date:l.date});pending-=used;if(!pending)break;}}$('dialog').close();open(`<h2>Revisa lo que vas a utilizar</h2><p class="hint">${r.name} · ${state.servings} raciones. Se priorizan los lotes utilizables con fecha más próxima.</p><ul class="review-list">${deductions.map(i=>`<li><span>${i.name}<small class="hint"> · ${i.date||'Fecha desconocida'}</small></span><strong>${i.qty} ${i.unit}</strong></li>`).join('')}</ul><p class="hint">Confirmación simulada. Solo cambia las existencias de esta pestaña.</p><div class="dialog-actions"><button class="button coral" id="confirm-cook">Confirmar que he cocinado</button><button class="button secondary" data-action="recipe-back" data-id="${id}">Volver a cantidades</button></div>`);$('confirm-cook').onclick=()=>{for(const i of deductions){const l=lots.find(l=>l.id===i.id);l.qty-=i.qty;}lots=lots.filter(l=>l.qty>0);$('dialog').close();render();$('content').classList.add('celebrate');toast('Receta confirmada en la demostración. Existencias actualizadas.');};}
function addForm(item=null,index=null){open(`<h2>${item?'Incorporar compra':'Añadir alimento ficticio'}</h2><p class="hint">La voz no está disponible en esta maqueta. Dictado pendiente de confirmación; utiliza el formulario.</p><form id="add-form"><label>Nombre ficticio<input id="lot-name" required maxlength="60" value="${esc(item?.name||'')}" placeholder="Ejemplo: Manzanas ficticias"></label><div class="form-grid"><label>Cantidad<input id="lot-qty" type="number" min="0.001" step="any" required value="${item?.qty||1}"></label><label>Unidad<select id="lot-unit">${['g','ml','ud'].map(u=>`<option ${u===item?.unit?'selected':''}>${u}</option>`).join('')}</select></label><label>Ubicación<select id="lot-place"><option>Nevera</option><option>Despensa</option><option>Congelador</option></select></label><label>Fecha opcional<input id="lot-date" type="date"></label></div><label>Tipo de fecha<select id="lot-type"><option>Caducidad</option><option>Consumo preferente</option></select></label><div class="dialog-actions"><button class="button coral">Revisar alimento</button></div></form>`);$('add-form').onsubmit=e=>{e.preventDefault();const draft={id:Date.now(),name:$('lot-name').value.trim(),qty:Number($('lot-qty').value),unit:$('lot-unit').value,place:$('lot-place').value,date:$('lot-date').value,type:$('lot-date').value?$('lot-type').value:'',icon:'🧺'};if(!draft.name||!(draft.qty>0)||!Number.isFinite(draft.qty))return;$('dialog').close();open(`<h2>Revisar nuevo lote</h2><ul class="review-list"><li><span>Alimento</span><strong>${esc(draft.name)}</strong></li><li><span>Cantidad</span><strong>${draft.qty} ${draft.unit}</strong></li><li><span>Ubicación</span><strong>${draft.place}</strong></li><li><span>Fecha</span><strong>${draft.date||'Fecha desconocida'}</strong></li>${draft.date?`<li><span>Tipo</span><strong>${draft.type}</strong></li>`:''}</ul><p class="hint">Solo datos ficticios. Guardado temporal en esta pestaña.</p><button class="button coral" id="save-lot">Confirmar lote ficticio</button>`);$('save-lot').onclick=()=>{lots.push(draft);if(index!==null)state.shop.splice(index,1);$('dialog').close();render();toast('Lote ficticio incorporado una sola vez.');};};}
document.addEventListener('change',e=>{if(e.target.matches('[data-shop]')){state.shop[Number(e.target.dataset.shop)].bought=e.target.checked;render();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='recipe')recipe(id);if(a==='recipe-back'){$('dialog').close();recipe(id);}if(a==='cook-review')cookReview(id);if(a==='recipe-tab'){state.recipeTab=id;render();}if(a==='add')addForm();if(a==='missing'){for(const i of missing(recipes.find(r=>r.id===id))){const same=state.shop.find(s=>s.name===i.name&&s.unit===i.unit&&!s.bought);if(same)same.qty=Math.max(same.qty,i.qty);else state.shop.push({...i,bought:false});}$('dialog').close();location.hash='compra';toast('Ingredientes pendientes añadidos, sin duplicar productos.');}if(a==='allergy'){state.allergies=state.allergies.includes(id)?state.allergies.filter(x=>x!==id):[...state.allergies,id];render();toast('Exclusión ficticia actualizada para las sugerencias.');}if(a==='shop-remove'){state.shop.splice(Number(id),1);render();}if(a==='incorporate')addForm(state.shop[Number(id)],Number(id));if(a==='shop-add'){open('<h2>Añadir a la compra</h2><form id="shop-form"><label>Producto ficticio<input id="shop-name" required maxlength="60" placeholder="Ejemplo: Manzanas ficticias"></label><label>Cantidad, en unidades<input id="shop-qty" type="number" min="1" step="1" value="1" required></label><div class="dialog-actions"><button class="button coral">Añadir producto ficticio</button></div></form>');$('shop-form').onsubmit=e=>{e.preventDefault();const name=$('shop-name').value.trim(),qty=Number($('shop-qty').value);if(!name||!Number.isInteger(qty)||qty<1)return;const same=state.shop.find(i=>i.name.toLowerCase()===name.toLowerCase()&&i.unit==='ud'&&!i.bought);if(same)same.qty+=qty;else state.shop.push({name,qty,unit:'ud',bought:false});$('dialog').close();render();};}if(a==='out'){const l=lots.find(l=>l.id===Number(id));open(`<h2>Registrar salida</h2><p>${esc(l.name)} · Lote ${l.id} · ${l.qty} ${l.unit}</p><form id="out-form"><label>Motivo<select id="out-reason"><option>Consumido directamente</option><option>Desechado</option><option>Utilizado al cocinar</option></select></label><label>Cantidad a revisar<input id="out-qty" type="number" min="0.001" max="${l.qty}" step="any" value="${l.qty}" required></label><div class="dialog-actions"><button class="button coral">Revisar salida</button></div></form>`);$('out-form').onsubmit=e=>{e.preventDefault();const qty=Number($('out-qty').value),reason=$('out-reason').value;if(!(qty>0)||qty>l.qty)return;$('dialog').close();open(`<h2>Confirmar salida ficticia</h2><p>${esc(l.name)}: ${qty} ${l.unit} · ${reason}.</p><p>Quedarán ${l.qty-qty} ${l.unit} en este lote.</p><button class="button coral" id="confirm-out">Confirmar salida</button>`);$('confirm-out').onclick=()=>{l.qty-=qty;lots=lots.filter(x=>x.qty>0);$('dialog').close();render();toast('Salida registrada en la demostración.');};};}if(a==='invite')open('<h2>Invitación ficticia</h2><p>La invitación real será de un solo uso y tendrá caducidad. Aquí se muestra el recorrido, sin enviar correos ni conceder acceso.</p><div class="notice prefer"><strong>Ejemplo de invitación</strong>Hogar del Olivo · 1 uso · Caduca en 7 días.</div>');if(a==='remove-member'){open('<h2>Retirar a Dani, miembro ficticio</h2><p>En la aplicación real perderá el acceso a los datos del hogar. Esta acción solo cambia la demostración.</p><button class="button coral" id="confirm-remove">Confirmar retirada ficticia</button>');$('confirm-remove').onclick=()=>{state.members=['Clara'];$('dialog').close();render();toast('Miembro ficticio retirado.');};}if(a==='privacy')open('<h2>Alergias reales: pendientes</h2><p>La demostración usa exclusivamente exclusiones ficticias. Antes de tratar alergias reales se necesita:</p><ul><li>Información de privacidad y finalidad concreta.</li><li>Autorización válida de cada persona afectada para el uso y el acceso compartido.</li><li>Permisos comprobados en el servidor, incluidos nuevos miembros.</li><li>Retirada, corrección y borrado comprobables.</li><li>Revisión de contratos y del recorrido de los datos.</li></ul><p>Una casilla no basta. La función permanece pendiente; no introduzcas información médica real.</p>');});
route();
